export default function ({ transcript }) {
  if (typeof transcript !== "string" || !transcript.trim()) throw Error("Provide a transcript");
  const chunks = [];
  for (let i = 0; i < transcript.length; i += 5000) {
    chunks.push(transcript.slice(i, i + 6000));
    if (i + 6000 >= transcript.length) break;
  }
  return { chunks };
}

