export default function ({ chunks, previous, answer }) {
  let i = previous?.i ?? 0,
    summary = previous?.summary ?? "";
  if (previous) {
    if (typeof answer !== "string" || !answer.trim()) throw Error("Empty summary");
    summary = answer.trim();
  }
  if (i >= chunks.length) return { state: { i, summary }, more: false, chunk: "", summary };
  return { state: { i: i + 1, summary }, more: true, chunk: chunks[i], summary };
}

