export default function ({ topics, previous, answer }) {
  let i = previous?.i ?? 0,
    items = previous?.items ?? [];
  if (previous) {
    if (typeof answer !== "string" || !answer.trim()) throw Error("Empty research");
    items = [...items, { topic: topics[i - 1].topic, research: answer.trim() }];
  }
  if (i >= topics.length) return { state: { i, items }, more: false, topic: "", why: "" };
  return { state: { i: i + 1, items }, more: true, topic: topics[i].topic, why: topics[i].why };
}

