export default function ({ summary, questions, items }) {
  const esc = (s) =>
    String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  return {
    html:
      "<p>Greetings 👋, here is your podcast digest.</p><h2>🎙 Episode Summary</h2><p>" +
      esc(summary) +
      "</p><h2>💡 Topics Discussed</h2>" +
      items.map((x) => "<h3>" + esc(x.topic) + "</h3><p>" + esc(x.research) + "</p>").join("") +
      "<h2>❓ Questions to Ponder</h2>" +
      questions.map((q) => "<h3>" + esc(q.question) + "</h3><p>" + esc(q.why) + "</p>").join(""),
  };
}

