export default async function ({ requestId, to }, ctx) {
  if (!requestId.trim() || !to.trim()) throw Error("Provide a request ID and recipient");
  const key = "podcast-digest:" + requestId;
  if (await ctx.state.get(key)) throw Error("Prior send attempt: inspect Gmail");
  await ctx.state.set(key, { status: "pending", to });
  return { key };
}

