export default function ({ query }) {
  if (!query.trim()) throw Error("Provide a search query");
  return {
    url:
      "https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrnamespace=0&gsrlimit=3&prop=extracts&exintro=1&explaintext=1&format=json&gsrsearch=" +
      encodeURIComponent(query),
  };
}

