export default function ({ body }) {
  if (!body || body.error) throw Error("Wikipedia search failed");
  const pages = Object.values(body.query?.pages || {}).map((x) => ({
    title: x.title,
    extract: x.extract,
  }));
  return { result: JSON.stringify(pages) };
}
